    cizKalemler(); cizDagilim(); durumRozeti(); onizleme(); sekme('yeni'); mesaj('info', `${esc(t.no)} düzenleme için açıldı (${esc(t.durum)}${t.durum === 'Reddedildi' ? '; kaydedince taslağa revize olur' : ''}).`);
