    const l = V.islemler.filter(t => (!ek || ek(t)) && (!d || t.durum === d) && (!tu || t.tur === tu) && (!ara || [t.no, t.grupMahsupNo, t.sirket, t.karsiSirket, t.borcCari, t.alacakCari, ...t.kalemler.map(k => k.belgeNo)].join(' ').toLocaleLowerCase('tr-TR').includes(ara)));
