    if (t.durum === 'Onay Bekliyor' && yetki('onay')) { e.push(btn('onayla', 'Onayla', 'btn-success', 'fa-check')); e.push(btn('reddet', 'Reddet', 'btn-outline-danger', 'fa-xmark')); }
    if ((t.durum === 'Onay Bekliyor' || t.durum === 'Onaylandı') && !t.erp.length) e.push(btn('gericek', 'Geri Çek', 'btn-light', 'fa-rotate-left'));
    if (t.durum === 'Onaylandı' && yetki('muhasebelestir')) e.push(`<span class="d-inline-flex align-items-center gap-1"><select class="form-select form-select-sm" data-senaryo="${t.no}" style="font-size:.66rem;min-height:24px;padding:1px 22px 1px 6px;width:auto">${SENARYOLAR.map(([k, a]) => `<option value="${k}">${a}</option>`).join('')}</select>${btn('muhasebelestir', t.yevmiye ? 'Muhasebeleştir (ERP)' : 'Mutabakat Oluştur (ERP)', 'btn-primary', 'fa-book')}</span>`);
    if ((t.durum === 'Kısmi Entegrasyon' || t.durum === 'Hata') && yetki('muhasebelestir')) e.push(btn('tekrar', 'Başarısız Tarafı Tekrar Dene', 'btn-warning', 'fa-rotate', 'title="Yalnız başarısız şirket / aksiyon tekrar; tamamlanan taraf mükerrer gönderilmez"'));
